export function buildGrade7Topic25Questions(topicCode: string): SeedQuestionItem[] {
  const rawList =
    GRADE7_CH1_CH2_TOPICS[topicCode] ||
    GRADE7_CH3_TOPICS[topicCode] ||
    GRADE7_CH4_TOPICS[topicCode];

  if (!rawList || rawList.length === 0) {
    return [];
  }

  return rawList.slice(0, 25).map((q, idx) => ({
    order_index: idx + 1,
    difficulty: q.difficulty,
    question_text: q.question_text,
    options: q.options,
    correct_index: q.correct_index,
    explanation: q.explanation,
  }));
}

/**
 * Generates 25 comprehensive synthesis exam questions for each Grade 7 Chapter
 * by combining balanced questions across all 3 topics of that chapter (9 + 8 + 8 = 25).
 */
export function buildGrade7Chapter25ExamQuestions(chapterCode: string): SeedQuestionItem[] {
  const topicCodesByChapter: Record<string, [string, string, string]> = {
    'G7-CH1': ['G7-C1-B1', 'G7-C1-B2', 'G7-C1-B3'],
    'G7-CH2': ['G7-C2-B1', 'G7-C2-B2', 'G7-C2-B3'],
    'G7-CH3': ['G7-C3-B1', 'G7-C3-B2', 'G7-C3-B3'],
    'G7-CH4': ['G7-C4-B1', 'G7-C4-B2', 'G7-C4-B3'],
  };

  const codes = topicCodesByChapter[chapterCode];
  if (!codes) return [];

  const t1 = buildGrade7Topic25Questions(codes[0]);
  const t2 = buildGrade7Topic25Questions(codes[1]);
  const t3 = buildGrade7Topic25Questions(codes[2]);

  // Pick 9 from Topic 1, 8 from Topic 2, 8 from Topic 3 across all difficulty levels
  const pickIndices9 = [0, 2, 5, 10, 12, 15, 17, 20, 22];
  const pickIndices8 = [0, 3, 6, 10, 13, 17, 20, 23];

  const combined: RawQ[] = [
    ...pickIndices9.map((i) => t1[i]).filter(Boolean),
    ...pickIndices8.map((i) => t2[i]).filter(Boolean),
    ...pickIndices8.map((i) => t3[i]).filter(Boolean),
  ];

  return combined.slice(0, 25).map((q, idx) => ({
    order_index: idx + 1,
    difficulty: q.difficulty,
    question_text: q.question_text,
    options: q.options,
    correct_index: q.correct_index,
    explanation: q.explanation,
  }));
}
